using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using Newtonsoft.Json;
public static class PropFinishImport{
 const string P="Assets/Afrer_Seconds/05.Model/Props/B5/";
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_PropFinish/"));
 static Material Mat(string n){var m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+n+".mat");if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,P+"Materials/"+n+".mat");}return m;}
 public static object Run(){var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(t+": "+m);};Application.logMessageReceived+=cb;try{
  var maps=new Dictionary<string,Texture2D>();
  foreach(string f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5/Textures"),"PF_*.png")){
   string n=Path.GetFileNameWithoutExtension(f),p=P+"Textures/"+Path.GetFileName(f);AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(p);
   bool normal=n.EndsWith("_Normal"),mos=n.EndsWith("_MOS"),decal=n.Contains("Decal");ti.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=!normal&&!mos;ti.alphaSource=mos?TextureImporterAlphaSource.FromInput:TextureImporterAlphaSource.None;ti.mipmapEnabled=true;ti.wrapMode=decal?TextureWrapMode.Clamp:TextureWrapMode.Repeat;ti.filterMode=FilterMode.Trilinear;ti.anisoLevel=4;ti.maxTextureSize=1024;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();maps[n]=AssetDatabase.LoadAssetAtPath<Texture2D>(p);
  }
  foreach(string f in new[]{"Coat","Blue","Steel","Dark","Rubber","Paper"}){
   var m=Mat("CP_"+f);m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",maps["PF_"+f+"_Base"]);m.SetTextureScale("_BaseMap",new Vector2(5,5));m.SetTexture("_BumpMap",maps["PF_"+f+"_Normal"]);m.SetFloat("_BumpScale",f=="Steel"?.38f:.25f);m.SetTexture("_MetallicGlossMap",maps["PF_"+f+"_MOS"]);m.SetFloat("_Metallic",1);m.SetFloat("_Smoothness",1);m.SetFloat("_SmoothnessTextureChannel",0);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);
  }
  foreach(var kv in maps.Where(k=>k.Key.StartsWith("PF_Decal_"))){var m=Mat(kv.Key);m.SetTexture("_BaseMap",kv.Value);m.SetColor("_BaseColor",Color.white);m.SetFloat("_Smoothness",.30f);m.SetFloat("_Metallic",0);m.SetFloat("_Cull",0);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}
  var glass=Mat("PF_Glass");glass.SetColor("_BaseColor",new Color(.56f,.74f,.77f,.14f));glass.SetFloat("_Surface",1);glass.SetFloat("_Blend",0);glass.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);glass.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);glass.SetFloat("_ZWrite",0);glass.SetFloat("_Cull",0);glass.SetFloat("_Smoothness",.88f);glass.SetFloat("_Metallic",0);glass.SetOverrideTag("RenderType","Transparent");glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.renderQueue=3000;glass.SetShaderPassEnabled("ShadowCaster",false);EditorUtility.SetDirty(glass);AssetDatabase.SaveAssetIfDirty(glass);
  var liquid=Mat("PF_Liquid");liquid.SetColor("_BaseColor",new Color(.09f,.30f,.34f));liquid.SetFloat("_Smoothness",.78f);liquid.SetFloat("_Metallic",0);EditorUtility.SetDirty(liquid);AssetDatabase.SaveAssetIfDirty(liquid);
  var mats=AssetDatabase.FindAssets("t:Material",new[]{P+"Materials"}).Select(g=>AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(g))).Where(m=>m.name.StartsWith("CP_")||m.name.StartsWith("ID_")||m.name.StartsWith("PF_")).ToDictionary(m=>m.name);
  int count=0;foreach(string f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5"),"*.fbx").Where(f=>Path.GetFileName(f).StartsWith("CP_")||Path.GetFileName(f).StartsWith("ID_"))){string p=P+Path.GetFileName(f);AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var im=(ModelImporter)AssetImporter.GetAtPath(p);im.importNormals=ModelImporterNormals.Import;im.importTangents=ModelImporterTangents.CalculateMikk;im.importAnimation=false;im.importCameras=false;im.importLights=false;im.isReadable=true;foreach(var kv in mats)im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);im.SaveAndReimport();count++;}
  var result=new{models=count,newTextures=maps.Count,logs};File.WriteAllText(H+"import.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }finally{Application.logMessageReceived-=cb;}}
}
